ST.xhtml:p:
MarkpointRtrig(CLK :=g_bMarkPointM); 
M315Trigger(CLK := g_bM315TriggerEnable);

dUWordCoord := FUN_FMOD(g_fUWorkCoordinate,FALSE);
IF dUWordCoord < 0.0 THEN
  dUWordCoord := dUWordCoord + 360.0;
END_IF;
IF M315Trigger.Q THEN
  g_bM315TriggerEnable := TRUE;
  (*对取余后的坐标值进行判断*)
  IF (dUWordCoord >=0.0 AND dUWordCoord <= 0.5) OR (dUWordCoord >=359.5 AND dUWordCoord <= 360.5) THEN
    g_noCurrentAngleOnSurface := 0.0;
  ELSIF  (dUWordCoord >=89.5 AND dUWordCoord <= 90.5) THEN
    g_noCurrentAngleOnSurface := 90.0;
  ELSIF  (dUWordCoord >=179.5 AND dUWordCoord <= 180.5) THEN
    g_noCurrentAngleOnSurface := 180.0; 
  ELSIF  (dUWordCoord >=269.5 AND dUWordCoord <= 270.5) THEN
    g_noCurrentAngleOnSurface := 270.0;
  END_IF;
  IF M.PARAMETER_P[315] = 1.0 THEN
    bM315Trigger := TRUE;
  ELSIF M.PARAMETER_P[315] = 2.0 THEN
    bM315Trigger := FALSE;
  END_IF;
END_IF;

IF MarkpointRtrig.Q THEN  
  g_bMarkPointM := FALSE;
  IF M.PARAMETER_J[166] = 0.0 THEN
    nLevelSwitchOn := 1; 
  ELSE
    IF M.PARAMETER_K[166] =0.0 THEN
      nLevelSwitchOn := 10;
    ELSE
      nLevelSwitchOn := 20;
    END_IF;
  END_IF; 
  bCalibrateLevelDone := FALSE;
END_IF;

CASE nLevelSwitchOn OF
  0:
  nLevelSwitchOn := 0;
  1:
  IF LREAL_TO_INT(g_fMarkPointIdM) =1 THEN
    fMarkXPoint1Value := g_fMarkXPointValueM;      
    fMarkZPoint1Value := g_fZCoordinate; 
    dMoveDistance := M.PARAMETER_I[166];      
  ELSIF LREAL_TO_INT(g_fMarkPointIdM) =2 THEN
    fMarkXPoint2Value := g_fMarkXPointValueM;
    fMarkZPoint2Value := g_fZCoordinate;  
    g_foAngle :=ATAN((fMarkZPoint2Value-fMarkZPoint1Value)/(fMarkXPoint2Value-fMarkXPoint1Value))/3.14159*180.0;
     IF g_bFivePointsCenterEnable=FALSE AND g_bFourSideCenterStatusFb=FALSE AND bM315Trigger=FALSE THEN
      g_dAngle := g_diUMachineCoordinate - g_foAngle;
    END_IF;
    bCalibrateLevelDone := TRUE;
  END_IF; 
  nLevelSwitchOn := 0;
  10:
    g_foAngle := ATAN((fMarkZPoint1Value - fMarkZPoint2Value)/(2.0*dMoveDistance))/3.14159*180.0;
    nLevelSwitchOn := 0;
  20:
    g_foAngle := ATAN((fMarkZPoint1Value - fMarkZPoint2Value)*2.0/M.PARAMETER_K[166])/3.14159*180.0;
    nLevelSwitchOn := 0;
END_CASE;
